public void printStackTrace(PrintStream ps) {
        if (causeException == null || super.getCause() == null || causeException == super.getCause()) {
            super.printStackTrace(ps);
        } else synchronized (ps) {
            ps.println(this);
            causeException.printStackTrace(ps);
            super.printStackTrace(ps);
        }
    }
